/**
 * A heading and the names of customers or partners as Lucide glyphs with a name. Axes: layout (grid, row),
 * columns (2, 3, 4), item (name, icon only, tile), density, tone.
 */
import { type ReactNode } from "react";
import { Grid } from "../primitives/grid/grid";
import { Group } from "../primitives/group/group";
import { LucideIcon } from "../primitives/lucide-icon/lucide-icon";
import { Text } from "../primitives/text/text";
import { LogoRibbon } from "../blocks/logo-ribbon";
import { SectionFrame } from "../components/section-frame";
import { cn } from "../utils";
import type { Logo } from "./logo-cloud.types";

export type LogoCloudProps = {
  id: string;
  title: string;
  logos: Logo[];
  layout?: "grid" | "row";
  cols?: "2" | "3" | "4";
  item?: "name" | "icon" | "tile";
  tone?: "default" | "muted";
  density?: "roomy" | "default" | "compact";
};

export function LogoCloud({
  id,
  title,
  logos,
  layout = "grid",
  cols = "4",
  item = "name",
  tone = "default",
  density = "default",
}: LogoCloudProps) {
  return (
    <>
      {((layout as string) === "row") ? (
        <LogoRibbon id={id} title={title} logos={logos} tone={tone} density={density} />
      ) : (
        <SectionFrame id={id} title={title} tone={tone} density={density} align="center">
          <Grid
            cols={
              (cols as string) === "2" ? "2"
              : (cols as string) === "3" ? "2-3"
              : (cols as string) === "4" ? "2-4"
              : "3-6"
            }
            className="gap-4"
            data-testid="items"
          >
            {(logos ?? []).map((logo) => (
              <Group key={logo.id}
                gap="2"
                align="center"
                justify="center"
                className={cn(
                  "text-muted-foreground",
                  (((item as string) === "tile") ? "flex-col rounded p-4 inset-ring inset-ring-border" : "")
                )}
                data-testid="item"
              >
                <LucideIcon name={logo.icon} size={24} />
                <Text size="sm" weight="semibold" className={(((item as string) === "icon") ? "sr-only" : "")}>
                  {logo.name}
                </Text>
              </Group>
            ))}
          </Grid>
        </SectionFrame>
      )}
    </>
  );
}

